import { repositoryId } from "@compforge/harness-common";
/** Find the deepest owning component, including for a deleted repository-relative path. */
export function owner(layout, path) {
    let found;
    for (const component of layout.components) {
        const root = component.root;
        if (root === "." || path === root || path.startsWith(root + "/")) {
            if (!found || found.root === "." || root.length > found.root.length)
                found = component;
        }
    }
    return found;
}
/** Attach common identity behavior without changing existing inspect JSON or enumerable fields. */
export function repository(forge, path) {
    const value = { forge: { name: forge }, path };
    return Object.defineProperty(value, "id", { value: () => repositoryId(value) });
}
